List<dynamic> largestSmallestIntegers(List<int> lst) {
  var negatives = lst.where((x) => x < 0).toList();
  var positives = lst.where((x) => x > 0).toList();
  var largest = negatives.isNotEmpty ? negatives.reduce((a, b) => a > b ? a : b) : null;
  var smallest = positives.isNotEmpty ? positives.reduce((a, b) => a < b ? a : b) : null;
  return [largest, smallest];
}
